CREATE DATABASE IF NOT EXISTS smart_segment CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smart_segment;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('user','admin') NOT NULL DEFAULT 'user',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS routes (id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL);
CREATE TABLE IF NOT EXISTS stops (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,city VARCHAR(120) NOT NULL,code VARCHAR(30) NOT NULL,UNIQUE(route_id,code),route_id INT NOT NULL,stop_order INT NOT NULL,FOREIGN KEY(route_id) REFERENCES routes(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS buses (id INT AUTO_INCREMENT PRIMARY KEY,operator_name VARCHAR(160) NOT NULL,bus_number VARCHAR(80) NOT NULL UNIQUE,service_number VARCHAR(80) NOT NULL UNIQUE,bus_type VARCHAR(80) NOT NULL,total_seats INT NOT NULL,fare DECIMAL(10,2) NOT NULL,departure TIME NOT NULL,arrival TIME NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,route_id INT NOT NULL,FOREIGN KEY(route_id) REFERENCES routes(id));
CREATE TABLE IF NOT EXISTS bookings (id INT AUTO_INCREMENT PRIMARY KEY,booking_code VARCHAR(30) NOT NULL UNIQUE,user_id INT NULL,bus_id INT NOT NULL,route_id INT NOT NULL,travel_date DATE NOT NULL,from_stop_id INT NOT NULL,to_stop_id INT NOT NULL,status ENUM('held','confirmed','cancelled') NOT NULL DEFAULT 'held',total_fare DECIMAL(10,2) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(bus_id) REFERENCES buses(id),FOREIGN KEY(route_id) REFERENCES routes(id),FOREIGN KEY(from_stop_id) REFERENCES stops(id),FOREIGN KEY(to_stop_id) REFERENCES stops(id));
CREATE TABLE IF NOT EXISTS booking_segments (id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT NOT NULL,seat_number INT NOT NULL,from_stop_id INT NOT NULL,to_stop_id INT NOT NULL,fare DECIMAL(10,2) NOT NULL,FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE,FOREIGN KEY(from_stop_id) REFERENCES stops(id),FOREIGN KEY(to_stop_id) REFERENCES stops(id),INDEX(bus_segment_lookup(seat_number,from_stop_id,to_stop_id)));
CREATE TABLE IF NOT EXISTS passengers (id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT NOT NULL,segment_id INT NULL,full_name VARCHAR(160) NOT NULL,age INT NOT NULL,gender VARCHAR(30) NOT NULL,mobile VARCHAR(30) NOT NULL,email VARCHAR(190) NULL,id_proof_type VARCHAR(60) NOT NULL,id_proof_number VARCHAR(120) NOT NULL,FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE,FOREIGN KEY(segment_id) REFERENCES booking_segments(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS payments (id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT NOT NULL,method VARCHAR(40) NOT NULL,status ENUM('pending','paid','failed') NOT NULL DEFAULT 'pending',amount DECIMAL(10,2) NOT NULL,transaction_ref VARCHAR(80) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE);
